import type { Metadata } from "next";
import { siteConfig } from "@/config/site";
import type { Faq } from "@/content/faqs";
import type { Service } from "@/content/services";

export const absoluteUrl = (path = "/") => `${siteConfig.url}${path === "/" ? "" : path}`;

type PageMeta = {
  title: string;
  description: string;
  path: string;
  noIndex?: boolean;
};

/** Builds unique title, description, canonical, Open Graph and X/Twitter metadata for a page. */
/** Generated by app/opengraph-image.tsx. */
const shareImage = {
  url: "/opengraph-image",
  width: 1200,
  height: 630,
  alt: `${siteConfig.name}: ${siteConfig.tagline}`,
};

export function createMetadata({ title, description, path, noIndex }: PageMeta): Metadata {
  const url = absoluteUrl(path);
  return {
    title: { absolute: title },
    description,
    alternates: { canonical: url },
    openGraph: {
      type: "website",
      url,
      title,
      description,
      siteName: siteConfig.name,
      locale: siteConfig.locale,
      images: [shareImage],
    },
    twitter: {
      card: "summary_large_image",
      title,
      description,
      site: siteConfig.twitterHandle,
      creator: siteConfig.twitterHandle,
      images: [shareImage],
    },
    robots: noIndex ? { index: false, follow: true } : undefined,
  };
}

/* ─────────────── Structured data (schema.org JSON-LD) ─────────────── */

const ids = {
  website: `${siteConfig.url}/#website`,
  business: `${siteConfig.url}/#business`,
  person: `${siteConfig.url}/#atul-nema`,
};

const sameAs = siteConfig.socials.map((s) => s.href).filter((href) => href.startsWith("http"));

export function siteSchema() {
  return {
    "@context": "https://schema.org",
    "@graph": [
      {
        "@type": "WebSite",
        "@id": ids.website,
        url: siteConfig.url,
        name: siteConfig.name,
        description: siteConfig.description,
        inLanguage: siteConfig.language,
        publisher: { "@id": ids.business },
      },
      {
        "@type": "Person",
        "@id": ids.person,
        name: siteConfig.person.name,
        jobTitle: siteConfig.person.jobTitle,
        url: absoluteUrl("/about"),
        email: `mailto:${siteConfig.contact.email}`,
        telephone: siteConfig.contact.phoneHref,
        worksFor: { "@id": ids.business },
        knowsAbout: [
          "Search Engine Optimization",
          "Technical SEO",
          "Local SEO",
          "Content Strategy",
          "Ecommerce SEO",
        ],
        address: { "@type": "PostalAddress", addressCountry: siteConfig.contact.countryCode },
        ...(siteConfig.person.portrait ? { image: absoluteUrl(siteConfig.person.portrait) } : {}),
        ...(sameAs.length ? { sameAs } : {}),
      },
      {
        "@type": "ProfessionalService",
        "@id": ids.business,
        name: siteConfig.name,
        slogan: siteConfig.tagline,
        description: siteConfig.description,
        url: siteConfig.url,
        email: siteConfig.contact.email,
        telephone: siteConfig.contact.phoneHref,
        image: absoluteUrl("/opengraph-image"),
        founder: { "@id": ids.person },
        address: { "@type": "PostalAddress", addressCountry: siteConfig.contact.countryCode },
        areaServed: siteConfig.contact.areaServed.map((name) => ({ "@type": "Place", name })),
        priceRange: "On request",
        ...(sameAs.length ? { sameAs } : {}),
      },
    ],
  };
}

export function servicesSchema(services: Service[]) {
  return {
    "@context": "https://schema.org",
    "@graph": services.map((s) => ({
      "@type": "Service",
      "@id": `${absoluteUrl("/services")}#${s.slug}`,
      name: s.title,
      serviceType: s.title,
      description: s.description,
      url: `${absoluteUrl("/services")}#${s.slug}`,
      provider: { "@id": ids.business },
      areaServed: siteConfig.contact.areaServed.map((name) => ({ "@type": "Place", name })),
    })),
  };
}

export function faqSchema(faqs: Faq[]) {
  return {
    "@context": "https://schema.org",
    "@type": "FAQPage",
    mainEntity: faqs.map((f) => ({
      "@type": "Question",
      name: f.question,
      acceptedAnswer: { "@type": "Answer", text: f.answer },
    })),
  };
}

export type Crumb = { name: string; path: string };

export function breadcrumbSchema(crumbs: Crumb[]) {
  return {
    "@context": "https://schema.org",
    "@type": "BreadcrumbList",
    itemListElement: crumbs.map((c, i) => ({
      "@type": "ListItem",
      position: i + 1,
      name: c.name,
      item: absoluteUrl(c.path),
    })),
  };
}
